// Builds icons.svg from icons.json.
//
// The set's source markup leaves mask ids as a `${u}` placeholder, because 54 of
// the 174 icons carry a mask — a mark that crosses a wall needs a moat cut out
// of that wall, and a moat is a mask. Upstream's contract is that `${u}` is
// substituted with something unique per rendered instance.
//
// In a sprite the substitution is per SYMBOL, not per instance: a symbol is
// declared once and `<use>` clones it, and `url(#…)` inside the clone resolves
// against the original document. So one unique id per symbol is both necessary
// and sufficient — every `<use>` of `warning-fill` points at the same mask
// element, which is the correct behaviour.
//
// Leaving the placeholder literal is what the previously shipped sprite did, and
// it collapsed 54 masks onto 4 ids (`k${u}` ×30, `m${u}` ×16, `t${u}` ×8,
// `b${u}` ×2). Every reference then resolved to the first match in the document,
// so 30 different filled glyphs all rendered with `add-circle-fill`'s mask.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, '..');

const { grid, stroke, icons } = JSON.parse(readFileSync(join(pkg, 'icons.json'), 'utf8'));
const names = Object.keys(icons).sort();

// A symbol id is already unique across the sprite, so it is the natural seed.
const uniqueFor = (name) => name.replace(/[^a-zA-Z0-9_-]/g, '-');

const symbols = names.map((name) => {
  const inner = icons[name].replaceAll('${u}', `-${uniqueFor(name)}`);
  return `<symbol id="${name}" viewBox="0 0 ${grid} ${grid}">${inner}</symbol>`;
});

const svg = [
  `<svg xmlns="http://www.w3.org/2000/svg" style="display:none"`
  + ` data-open-icons="matthewlew/open-icons" data-grid="${grid}" data-stroke="${stroke}">`,
  '<defs>',
  ...symbols,
  '</defs>',
  '</svg>',
  '',
].join('\n');

writeFileSync(join(pkg, 'icons.svg'), svg);
writeFileSync(join(pkg, 'names.json'), JSON.stringify(names, null, 0) + '\n');

// Emitted as a module rather than imported from names.json at runtime: JSON
// import attributes are still uneven across bundlers, and this makes the name
// list a plain ESM import that every toolchain already understands.
writeFileSync(
  join(pkg, 'src', 'names.js'),
  '// Generated by scripts/build-sprite.mjs. Do not edit.\n'
  + `export default ${JSON.stringify(names, null, 0)};\n`,
);

// A placeholder that survives into the output is the bug this script exists to
// prevent, so it fails the build rather than shipping.
if (svg.includes('${u}')) {
  console.error('build-sprite: unsubstituted ${u} placeholder in output');
  process.exit(1);
}

const masked = names.filter((n) => icons[n].includes('${u}'));
console.log(`build-sprite: ${names.length} symbols, ${masked.length} masked ids made unique`);
